//! Renders source manifests and module registries into schema aggregate files.

mod runtime_api;

use crate::compile::CompiledSchema;
use crate::config::ResolvedBindings;
use crate::error::CodegenError;
use crate::writer::{GeneratedFile, rust_comment_text, rust_string_literal};

use self::runtime_api::render_runtime_api;

const GENERATED_HEADER: &str =
    "// This file was generated by Chigiri.\n// Do not edit manually.\n\n";

pub(super) fn render_scaffold(
    compiled: &CompiledSchema,
    generated: &[GeneratedFile],
    bindings: &ResolvedBindings,
    resolver_abi_fingerprint: chigiri_core::executor::ResolverSchemaFingerprint,
    schema_digest: chigiri_core::SchemaDigest,
) -> Result<Vec<GeneratedFile>, CodegenError> {
    let mut files = render_source_manifests(compiled);
    let modules = collect_modules(generated)?;
    let indices = vec![render_registry(&modules)];
    files.push(render_private_root(
        &indices,
        bindings,
        resolver_abi_fingerprint,
        schema_digest,
    ));
    files.extend(indices);
    for file in &mut files {
        file.name = format!("__chigiri/{}", file.name);
    }
    files.push(render_public_root());
    Ok(files)
}

fn render_source_manifests(compiled: &CompiledSchema) -> Vec<GeneratedFile> {
    let mut contents = String::from(GENERATED_HEADER);
    contents.push_str("// Inputsource:\n");
    for source in &compiled.sources {
        contents.push_str("// - ");
        contents.push_str(&rust_comment_text(&source.relative_path));
        contents.push('\n');
    }
    vec![GeneratedFile {
        name: "sources.rs".to_owned(),
        contents,
        exports_public_items: false,
    }]
}

struct Module {
    path: String,
    name: String,
    public: bool,
    import: bool,
}

fn collect_modules(files: &[GeneratedFile]) -> Result<Vec<Module>, CodegenError> {
    let mut modules = Vec::new();
    let mut used = std::collections::BTreeSet::new();
    for file in files {
        let stem = file.name.strip_suffix(".rs").ok_or_else(|| {
            CodegenError::new("SF4010", "The generated file name does not end in .rs.")
        })?;
        // Avoid keyword collisions and repeated-underscore lints with separate suffixes.
        let encoded = stem.replace('_', "_u").replace('/', "_p");
        let name = format!("__chigiri_{encoded}");
        if !used.insert(name.clone()) {
            return Err(CodegenError::new("SF4006", "Private module names collide."));
        }
        let import = file.exports_public_items
            || file.contents.lines().any(|line| {
                [
                    "pub(super) fn ",
                    "pub(super) const ",
                    "pub(super) static ",
                    "pub(super) struct ",
                    "pub struct ",
                    "pub type ",
                ]
                .iter()
                .any(|prefix| line.starts_with(prefix))
            });
        modules.push(Module {
            path: file.name.clone(),
            name,
            public: file.exports_public_items,
            import,
        });
    }
    Ok(modules)
}

fn render_registry(modules: &[Module]) -> GeneratedFile {
    let mut contents = String::from(GENERATED_HEADER);
    for module in modules {
        contents.push_str(&format!(
            "#[path = {}]\nmod {};\n",
            rust_string_literal(&module.path),
            module.name
        ));
        if module.import {
            let visibility = if module.public { "pub " } else { "" };
            contents.push_str(&format!("{visibility}use {}::*;\n", module.name));
        }
    }
    GeneratedFile {
        name: "modules.rs".to_owned(),
        contents,
        exports_public_items: false,
    }
}

fn render_private_root(
    indices: &[GeneratedFile],
    bindings: &ResolvedBindings,
    resolver_abi_fingerprint: chigiri_core::executor::ResolverSchemaFingerprint,
    schema_digest: chigiri_core::SchemaDigest,
) -> GeneratedFile {
    let mut contents = String::from(GENERATED_HEADER);
    contents.push_str(
        "// The schema is one immutable descriptor shared by generated types and coercion.\n",
    );
    contents.push_str("// generated ABI version: 8\n");
    contents.push_str("// The ordered input source list is recorded in sources.rs.\n");
    contents.push_str(&format!(
        "// schema content SHA-256: {}\n",
        schema_digest.to_hex()
    ));
    if let Some(provenance) = bindings.provenance() {
        contents.push_str(&format!(
            "// enum binding config: {}\n// enum binding config SHA-256: {}\n\n",
            rust_comment_text(provenance.label()),
            provenance.digest_hex()
        ));
    } else {
        contents.push_str("// enum binding config: none\n// enum binding config SHA-256: none\n\n");
    }
    contents.push_str("const _: () = assert!(\n");
    contents.push_str("    ::chigiri::GENERATED_ABI_VERSION == 8,\n");
    contents.push_str(&format!(
        "    {},\n",
        rust_string_literal("generated code is incompatible with this Chigiri runtime ABI")
    ));
    contents.push_str(");\n\n");
    for index in indices {
        contents.push_str(&format!(
            "include!({});\n",
            rust_string_literal(&index.name)
        ));
    }
    contents
        .push_str("\n/// Static schema descriptor; the runtime does not parse the SDL again.\n");
    contents.push_str("pub static SCHEMA_DESCRIPTOR: ::chigiri::SchemaDescriptor = ");
    contents.push_str("GENERATED_SCHEMA_DESCRIPTOR;\n");
    contents.push_str("\nconst GENERATED_RESOLVER_ABI_FINGERPRINT: ::chigiri::__private::ResolverSchemaFingerprint =\n    ");
    contents.push_str(&format!(
        "::chigiri::__private::ResolverSchemaFingerprint::new({}, {}_u64);\n",
        resolver_abi_fingerprint.component_count(),
        resolver_abi_fingerprint.hash()
    ));
    render_runtime_api(&mut contents);
    contents.push('\n');
    GeneratedFile {
        name: "mod.rs".to_owned(),
        contents,
        exports_public_items: false,
    }
}

fn render_public_root() -> GeneratedFile {
    let mut contents = String::from(GENERATED_HEADER);
    contents.push_str("const _: () = assert!(\n");
    contents.push_str("    ::chigiri::GENERATED_ABI_VERSION == 8,\n");
    contents.push_str("\" chigiri generated ABI mismatch; please recreate the schema \", \n");
    contents.push_str(");\n\n");
    contents.push_str("#[doc(hidden)]\nmod __chigiri;\n");
    contents.push_str("pub use __chigiri::*;\n");
    GeneratedFile {
        name: "mod.rs".to_owned(),
        contents,
        exports_public_items: false,
    }
}

